import 'dart:convert';
import 'dart:io';

import 'package:dio/dio.dart';
import 'package:flutter_test/flutter_test.dart';

import 'mock_dio_adapter.dart';

/// Offline conformance checker: validates real outgoing requests against the
/// ThingsBoard OpenAPI snapshot in `test/fixtures/contract/`.
///
/// The snapshot is generated by `tools/api_contract/build_subset.py`
/// (see `docs/qa/API_CONTRACT.md`). It never needs the network.
class OpenApiContract {
  OpenApiContract._(
    this.version,
    this._operations,
    this._schemas,
    this._knownDeviations,
    this._allowedQuery,
    this._skipResponse,
  );

  factory OpenApiContract.load([
    String path = 'test/fixtures/contract/tb_pe_4_4_1_subset.json',
    String deviationsPath = 'tools/api_contract/known_deviations.json',
  ]) {
    final json =
        jsonDecode(File(path).readAsStringSync()) as Map<String, dynamic>;
    final deviations =
        jsonDecode(File(deviationsPath).readAsStringSync())
            as Map<String, dynamic>;
    return OpenApiContract._(
      json['specVersion'] as String,
      (json['operations'] as Map<String, dynamic>).cast<String, dynamic>(),
      ((json['schemas'] as Map<String, dynamic>?) ?? const {}),
      ((deviations['endpoints'] as Map<String, dynamic>?) ?? const {}).keys
          .toSet(),
      {
        for (final e
            in ((deviations['query_params'] as Map<String, dynamic>?) ??
                    const {})
                .entries)
          e.key: ((e.value as Map<String, dynamic>)['allow'] as List<dynamic>)
              .cast<String>()
              .toSet(),
      },
      ((deviations['responses'] as Map<String, dynamic>?) ?? const {}).keys
          .toSet(),
    );
  }

  final String version;
  final Map<String, dynamic> _operations;

  /// Compact schema graph reachable from the operations (see build_subset.py).
  final Map<String, dynamic> _schemas;

  /// Reviewed paths absent from the spec on purpose (Community Edition
  /// fallbacks). Single source of truth: `tools/api_contract/known_deviations.json`.
  final Set<String> _knownDeviations;

  /// Reviewed query parameters tolerated on a given `METHOD /template`
  /// (version-compat fallbacks the spec does not describe).
  final Map<String, Set<String>> _allowedQuery;

  /// Operations whose documented response shape is known to be wrong
  /// (`known_deviations.json` -> `responses`), so it is not validated.
  final Set<String> _skipResponse;

  /// Every `METHOD /template` in the snapshot (for coverage assertions).
  Set<String> get operationKeys => _operations.keys.toSet();

  /// Spec operation key matched by a concrete request, or `null`.
  String? matchOperation(String method, String path) {
    final segments = _segments(path);
    String? best;
    var bestScore = -1;
    for (final key in _operations.keys) {
      final space = key.indexOf(' ');
      if (key.substring(0, space) != method.toUpperCase()) continue;
      final template = _segments(key.substring(space + 1));
      if (template.length != segments.length) continue;
      var score = 0;
      var ok = true;
      for (var i = 0; i < template.length; i++) {
        if (template[i].startsWith('{')) continue;
        if (template[i] == segments[i]) {
          score++;
        } else {
          ok = false;
          break;
        }
      }
      if (ok && score > bestScore) {
        best = key;
        bestScore = score;
      }
    }
    return best;
  }

  /// Returns human-readable violations (empty when the request conforms).
  List<String> validate(RequestOptions options) {
    final method = options.method.toUpperCase();
    final path = options.path.split('?').first;
    final label = '$method $path';
    final key = matchOperation(method, path);
    if (key == null) {
      if (_knownDeviations.contains(path)) return const [];
      final others = [
        for (final m in const ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'])
          if (m != method && matchOperation(m, path) != null) m,
      ];
      return [
        '$label: no such operation in ThingsBoard $version'
            '${others.isEmpty ? '' : ' (spec has: ${others.join(', ')})'}',
      ];
    }

    final op = _operations[key] as Map<String, dynamic>;
    final violations = <String>[];
    final params = (op['parameters'] as List<dynamic>)
        .cast<Map<String, dynamic>>();
    final queryDefs = {
      for (final p in params.where((p) => p['in'] == 'query'))
        p['name'] as String: p,
    };

    // Path parameters with a closed value set (e.g. attribute `scope`).
    final templateSegments = _segments(key.substring(key.indexOf(' ') + 1));
    final concreteSegments = _segments(path);
    for (var i = 0; i < templateSegments.length; i++) {
      final segment = templateSegments[i];
      if (!segment.startsWith('{')) continue;
      final name = segment.substring(1, segment.length - 1);
      for (final p in params.where((p) => p['in'] == 'path')) {
        final allowed = p['enum'] as List<dynamic>?;
        if (p['name'] == name &&
            allowed != null &&
            !allowed.contains(Uri.decodeComponent(concreteSegments[i]))) {
          violations.add(
            '$label: path `$name`=`${concreteSegments[i]}` '
            'is not one of ${allowed.join('|')}',
          );
        }
      }
    }

    options.queryParameters.forEach((name, value) {
      final def = queryDefs[name];
      if (def == null) {
        if (_allowedQuery[key]?.contains(name) ?? false) return;
        violations.add('$label: unknown query parameter `$name` (spec: $key)');
        return;
      }
      if (value == null) {
        violations.add('$label: query parameter `$name` is null');
        return;
      }
      final values = value is Iterable ? value.toList() : [value];
      final enumValues =
          (def['enum'] as List<dynamic>?) ??
          ((def['items'] as Map<String, dynamic>?)?['enum'] as List<dynamic>?);
      for (final v in values) {
        if (enumValues != null && !enumValues.contains(v.toString())) {
          violations.add(
            '$label: `$name`=`$v` is not one of ${enumValues.join('|')}',
          );
        }
        final type =
            def['type'] ?? (def['items'] as Map<String, dynamic>?)?['type'];
        if (type == 'integer' && int.tryParse(v.toString()) == null) {
          violations.add('$label: `$name`=`$v` is not an integer');
        }
        if (type == 'boolean' &&
            v.toString() != 'true' &&
            v.toString() != 'false') {
          violations.add('$label: `$name`=`$v` is not a boolean');
        }
      }
    });
    for (final entry in queryDefs.entries) {
      if (entry.value['required'] == true &&
          !options.queryParameters.containsKey(entry.key)) {
        violations.add(
          '$label: required query parameter `${entry.key}` missing',
        );
      }
    }

    // Required header parameters (e.g. `X-Mobile-Token`). `X-Authorization` is
    // a security scheme, not a declared parameter, so it is not checked here.
    final sentHeaders = {for (final h in options.headers.keys) h.toLowerCase()};
    for (final p in params.where((p) => p['in'] == 'header')) {
      final name = p['name'] as String;
      if (p['required'] == true && !sentHeaders.contains(name.toLowerCase())) {
        violations.add('$label: required header `$name` missing');
      }
    }

    final body = op['body'] as Map<String, dynamic>?;
    final data = options.data;
    final hasData =
        data != null &&
        !(data is Map && data.isEmpty) &&
        !(data is String && data.isEmpty);
    if (body == null) {
      if (hasData) {
        violations.add('$label: sends a body but the spec defines none');
      }
    } else {
      if (body['required'] == true && data == null) {
        violations.add('$label: required request body is missing');
      }
      if (hasData && body['free'] != true) {
        // Checks types, enums, unknown and required fields, nested too.
        violations.addAll(
          _validateJson(
            data,
            body['node'] as Map<String, dynamic>,
            what: 'body',
            label: label,
          ),
        );
      }
    }
    return violations;
  }

  /// Violations of a JSON-decoded [response] against the spec's 2xx schema.
  /// Error statuses and empty bodies are skipped.
  List<String> validateResponse(CapturedResponse response) {
    final json = response.json;
    if (json == null ||
        response.statusCode < 200 ||
        response.statusCode > 299) {
      return const [];
    }
    final request = response.request;
    final path = request.path.split('?').first;
    final key = matchOperation(request.method, path);
    if (key == null) return const []; // reported by the request validation
    if (_skipResponse.contains(key)) return const [];
    final node =
        (_operations[key] as Map<String, dynamic>)['responseNode']
            as Map<String, dynamic>?;
    if (node == null) return const [];
    return _validateJson(
      json,
      node,
      what: 'response',
      label: '${request.method.toUpperCase()} $path',
    );
  }

  /// Recursively validates [value] against a snapshot schema [node]: JSON type,
  /// enum, required and unknown object fields. `null` values and polymorphic or
  /// too-deep schemas (`free`) are accepted.
  List<String> _validateJson(
    Object? value,
    Map<String, dynamic> node, {
    required String what,
    required String label,
    String at = r'$',
    int depth = 0,
  }) {
    if (value == null || node['free'] == true || depth > 12) return const [];
    final ref = node['ref'] as String?;
    if (ref != null) {
      final target = _schemas[ref];
      if (target == null) return const []; // beyond the snapshot's depth limit
      return _validateJson(
        value,
        target as Map<String, dynamic>,
        what: what,
        label: label,
        at: at,
        depth: depth + 1,
      );
    }

    final violations = <String>[];
    final enumValues = node['enum'] as List<dynamic>?;
    if (enumValues != null && !enumValues.contains(value)) {
      violations.add(
        '$label: $what `$at`=`$value` is not one of ${enumValues.join('|')}',
      );
    }

    switch (node['type']) {
      case 'string' when value is! String:
      case 'boolean' when value is! bool:
      case 'number' when value is! num:
      case 'array' when value is! List:
      case 'object' when value is! Map:
        violations.add(
          '$label: $what `$at` should be ${node['type']} but is '
          '${value.runtimeType}',
        );
        return violations;
      case 'integer'
          when !(value is int || (value is double && value % 1 == 0)):
        violations.add('$label: $what `$at` should be integer but is `$value`');
        return violations;
    }

    if (value is List) {
      final items = node['items'] as Map<String, dynamic>?;
      if (items != null) {
        for (var i = 0; i < value.length; i++) {
          violations.addAll(
            _validateJson(
              value[i],
              items,
              what: what,
              label: label,
              at: '$at[$i]',
              depth: depth + 1,
            ),
          );
        }
      }
    } else if (value is Map) {
      final props = node['props'] as Map<String, dynamic>?;
      final additional = node['additional'] as Map<String, dynamic>?;
      if (props != null) {
        for (final entry in value.entries) {
          final child = props[entry.key];
          if (child == null) {
            violations.add(
              '$label: unknown $what field `${entry.key}` at `$at`',
            );
          } else {
            violations.addAll(
              _validateJson(
                entry.value,
                child as Map<String, dynamic>,
                what: what,
                label: label,
                at: '$at.${entry.key}',
                depth: depth + 1,
              ),
            );
          }
        }
        for (final name in (node['required'] as List<dynamic>? ?? const [])) {
          if (!value.containsKey(name)) {
            violations.add(
              '$label: required $what field `$name` missing at `$at`',
            );
          }
        }
      } else if (additional != null) {
        for (final entry in value.entries) {
          violations.addAll(
            _validateJson(
              entry.value,
              additional,
              what: what,
              label: label,
              at: '$at.${entry.key}',
              depth: depth + 1,
            ),
          );
        }
      }
    }
    return violations;
  }

  /// Fails the test listing every violation across [requests].
  void expectConforms(Iterable<RequestOptions> requests) {
    final all = <String>[];
    for (final request in requests) {
      all.addAll(validate(request));
    }
    expect(all, isEmpty, reason: 'Contract violations:\n${all.join('\n')}');
  }

  /// Fails the test listing every response-shape violation across [responses]:
  /// proves the fixtures are as real as the server's payloads.
  void expectResponsesConform(Iterable<CapturedResponse> responses) {
    final all = <String>[];
    for (final response in responses) {
      all.addAll(validateResponse(response));
    }
    expect(
      all,
      isEmpty,
      reason: 'Response/fixture violations:\n${all.take(40).join('\n')}',
    );
  }

  /// Requests AND responses of [adapter] must both conform to the spec.
  void expectAllConform(MockDioAdapter adapter) {
    expectConforms(adapter.capturedRequests);
    expectResponsesConform(adapter.capturedResponses);
  }

  /// Spec operation keys exercised by [requests] (use to assert coverage).
  Set<String> coveredOperations(Iterable<RequestOptions> requests) {
    final covered = <String>{};
    for (final r in requests) {
      final key = matchOperation(r.method, r.path.split('?').first);
      if (key != null) covered.add(key);
    }
    return covered;
  }

  static List<String> _segments(String path) =>
      path.split('?').first.split('/').where((s) => s.isNotEmpty).toList();
}
